create table if not exists tka_stimuli (stimulus_id uuid primary key, stimulus_type text not null, content text not null, created_at timestamptz not null default now());
create table if not exists tka_questions (question_id uuid primary key, exam_id uuid not null references tka_exams(exam_id), number integer not null, question_type text not null check (question_type in ('PG','MCMA','CATEGORY')), prompt text not null, options jsonb not null default '[]'::jsonb, stimulus_id uuid references tka_stimuli(stimulus_id), metadata jsonb not null default '{}'::jsonb, unique(exam_id,number));
